<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Development extends AdminController {
 public function __construct(){ parent::__construct(); $this->load->model('development/development_model'); if(!is_admin()&&!staff_can('view','development'))access_denied(_l('dev_development')); }
 private function can($c){ return is_admin()||staff_can($c,'development'); }
 private function staff(){ return $this->db->select('staffid,firstname,lastname,email')->where('active',1)->order_by('firstname')->get(db_prefix().'staff')->result_array(); }
 private function clean_url($u){ $u=trim((string)$u); if($u==='')return ''; return filter_var($u,FILTER_VALIDATE_URL)?$u:''; }
 public function index(){ $this->load->view('development/list',['title'=>_l('dev_development'),'items'=>$this->development_model->all()]); }
 public function create(){ if(!$this->can('create'))access_denied(_l('dev_development')); if($this->input->post()){ $title=trim((string)$this->input->post('title')); $desc=trim((string)$this->input->post('description')); if($title===''){$title=mb_substr($desc,0,120);if($title==='')$title=_l('dev_new_repair');} $id=$this->development_model->create(['title'=>$title,'description'=>$desc,'reference_url'=>$this->clean_url($this->input->post('reference_url')),'estimated_hours'=>$this->hours($this->input->post('estimated_hours'))]); if($this->can('assign'))$this->development_model->set_assignees($id,$this->input->post('assignees')); $this->upload_files($id,null); set_alert('success',_l('dev_created')); redirect(admin_url('development/view/'.$id)); } $this->load->view('development/form',['title'=>_l('dev_new_repair'),'item'=>null,'staff'=>$this->staff()]); }
 public function edit($id){ if(!$this->can('edit'))access_denied(_l('dev_development')); $item=$this->development_model->get($id);if(!$item)show_404(); if($this->input->post()){ $this->development_model->update_item($id,['title'=>trim((string)$this->input->post('title')),'description'=>trim((string)$this->input->post('description')),'reference_url'=>$this->clean_url($this->input->post('reference_url')),'estimated_hours'=>$this->hours($this->input->post('estimated_hours'))]); if($this->can('assign'))$this->development_model->set_assignees($id,$this->input->post('assignees')); $this->upload_files($id,null); set_alert('success',_l('dev_saved'));redirect(admin_url('development/view/'.$id)); } $this->load->view('development/form',['title'=>_l('dev_edit_repair'),'item'=>$item,'staff'=>$this->staff()]); }
 public function view($id){ $item=$this->development_model->get($id);if(!$item)show_404();$this->load->view('development/view',['title'=>$item['title'],'item'=>$item]); }
 public function note($id){ if(!$this->can('notes'))access_denied(_l('dev_development'));$item=$this->development_model->get($id);if(!$item)show_404();$note=trim((string)$this->input->post('note'));$next=trim((string)$this->input->post('next_step'));$sent=count(array_filter((array)($_FILES['attachments']['name']??[])));if($note!==''||$next!==''||$sent){$nid=$this->development_model->add_note($id,$note,$next);$saved=$this->upload_files($id,$nid);set_alert($saved<$sent?'warning':'success',_l($saved<$sent?'dev_files_rejected':'dev_note_added'));}else set_alert('warning',_l('dev_note_empty'));redirect(admin_url('development/view/'.$id)); }
 public function complete($id){ if(!$this->can('complete'))access_denied(_l('dev_development'));$item=$this->development_model->get($id);if(!$item)show_404();$this->development_model->complete($id,$item['status']!=='completed');redirect(admin_url('development/view/'.$id)); }
 public function delete($id){
  if(!$this->can('delete'))access_denied(_l('dev_development'));
  if($this->input->method(true)!=='POST'){ show_error(_l('dev_delete_post_required'),405); return; }
  if(!ctype_digit((string)$id)||(int)$id<1||!$this->development_model->get((int)$id)){ show_404(); return; }
  $deleted=$this->development_model->delete_item((int)$id);
  set_alert($deleted?'success':'danger',_l($deleted?'dev_deleted':'dev_delete_failed'));
  redirect(admin_url('development'));
 }
 public function file($aid){ $a=$this->development_model->attachment($aid);if(!$a)show_404();$f=$this->development_model->upload_dir($a['item_id']).$a['stored_name'];if(!is_file($f))show_404();$this->output->set_content_type($a['mime_type']?:'application/octet-stream');$this->output->set_header('Content-Disposition: inline; filename="'.str_replace('"','',$a['original_name']).'"');$this->output->set_output(file_get_contents($f)); }
 private function hours($v){ $v=(float)$v;return $v>0?min($v,9999):null; }
 private function upload_files($id,$note_id){ $saved=0; if(empty($_FILES['attachments']['name']))return 0; $names=$_FILES['attachments']['name']; if(!is_array($names))$names=[$names]; $allowed=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime']; $dir=$this->development_model->upload_dir($id); if(!is_dir($dir))@mkdir($dir,0755,true); foreach($names as $i=>$orig){ if(!$orig)continue;$tmp=is_array($_FILES['attachments']['tmp_name'])?$_FILES['attachments']['tmp_name'][$i]:$_FILES['attachments']['tmp_name'];$err=is_array($_FILES['attachments']['error'])?$_FILES['attachments']['error'][$i]:$_FILES['attachments']['error'];$size=is_array($_FILES['attachments']['size'])?$_FILES['attachments']['size'][$i]:$_FILES['attachments']['size'];if($err!==UPLOAD_ERR_OK||!is_uploaded_file($tmp))continue;$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($tmp);if(!in_array($mime,$allowed,true))continue;$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','video/mp4'=>'mp4','video/webm'=>'webm','video/quicktime'=>'mov'][$mime];$stored=bin2hex(random_bytes(16)).'.'.$ext;if(move_uploaded_file($tmp,$dir.$stored)){$this->development_model->add_attachment($id,$note_id,basename($orig),$stored,$mime,$size);$saved++;} } return $saved; }
}
